      val r19 = compute_case_C20StartWork(api_intentFact, api_materialFact, api_targetFact, api_authorization, api_reasonToStatus)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7 & r8 & r9 & r10 & r11 & r12 & r13 & r14 & r15 & r16 & r17 & r18 & r19
    }

